from z3 import *

def solve_latin_square(grid):
    # Create a 9x9 matrix of variables
    s = Solver()
    X = [[Int(f"x_{i}_{j}") for j in range(9)] for i in range(9)]

    # Add constraints for each cell (0-8)
    for i in range(9):
        for j in range(9):
            s.add(X[i][j] >= 0, X[i][j] <= 8)

    # Add pre-filled clues
    for i in range(9):
        for j in range(9):
            val = grid[i * 9 + j]
            if val != -1:
                s.add(X[i][j] == val)

    # Add row constraints
    for i in range(9):
        s.add(Distinct([X[i][j] for j in range(9)]))

    # Add column constraints
    for j in range(9):
        s.add(Distinct([X[i][j] for i in range(9)]))

    if s.check() == sat:
        m = s.model()
        result = []
        for i in range(9):
            for j in range(9):
                result.append(m.evaluate(X[i][j]).as_long())
        return result
    else:
        return None

